export function AdminVariants(){const{api}=useSession(),toast=useToast(),variants=useLoad<Variant[]>(s=>api.admin<Variant[]>("variants",s)),products=useLoad<Product[]>(s=>api.admin<Product[]>("products",s)),[search,setSearch]=useState(""),[edit,setEdit]=useState<Variant|null|undefined>(undefined),[draft,setDraft]=useState({productId:"",name:"",variantSku:"",isActive:true}),[saving,setSaving]=useState(false),names=Object.fromEntries((products.data??[]).map(p=>[p.id,p.title])),rows=(variants.data??[]).filter(v=>!search||`${v.name} ${v.variantSku} ${names[v.productId]??""}`.toLowerCase().includes(search.toLowerCase())),open=(variant?:Variant)=>{setEdit(variant??null);setDraft(variant?{productId:variant.productId,name:variant.name,variantSku:variant.variantSku,isActive:variant.isActive}:{productId:String(products.data?.[0]?.id??""),name:"",variantSku:"",isActive:true})},save=async()=>{setSaving(true);try{const input={productId:Number(draft.productId),name:draft.name,variantSku:draft.variantSku,isActive:draft.isActive};edit?await api.updateVariant(edit.id,input):await api.createVariant(input);setEdit(undefined);variants.reload();toast.push({tone:"success",title:"Variant saved"})}catch(e){toast.push({tone:"error",title:"Variant save failed",message:errorMessage(e)})}finally{setSaving(false)}};
  return <><PageHeader eyebrow="Catalog" title="Variants" description="Sellable sizes and options. Inventory is tracked per variant." action={<button className="btn" type="button" onClick={()=>open()}><Icon name="plus"/>Add variant</button>}/>{catalogNote}<div className="toolbar"><label className="search"><span className="sr-only">Search variants</span><Icon name="search"/><input type="search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search product, size, or SKU"/></label></div><section className="panel flush"><Body state={{...variants,data:variants.data?rows:null}} empty={<Empty icon="grid" message="No variants match."/>}>{list=><div className="table-wrap"><table><thead><tr><th>Product</th><th>Variant</th><th className="hide-sm">Variant SKU</th><th>Status</th><th/></tr></thead><tbody>{list.map(v=><tr key={v.id}><td>{names[v.productId]??`Product #${v.productId}`}</td><td><strong>{v.name}</strong></td><td className="hide-sm mono">{v.variantSku}</td><td><StatusBadge value={v.isActive?"Healthy":"Expired"} label={v.isActive?"Active":"Inactive"}/></td><td><button className="btn btn-sm btn-secondary" type="button" onClick={()=>open(v)}>Edit</button></td></tr>)}</tbody></table></div>}</Body></section>{edit!==undefined&&<Modal title={edit?"Edit variant":"Add variant"} onClose={()=>!saving&&setEdit(undefined)} footer={<><button className="btn btn-secondary" type="button" onClick={()=>setEdit(undefined)}>Cancel</button><button className="btn" type="button" disabled={saving||!draft.productId||!draft.name||!draft.variantSku} onClick={()=>void save()}>{saving?"Saving…":"Save variant"}</button></>}><div className="form-grid"><label className="field"><span>Product</span><select value={draft.productId} onChange={e=>setDraft({...draft,productId:e.target.value})}>{(products.data??[]).map(p=><option key={p.id} value={p.id}>{p.title}</option>)}</select></label><label className="field"><span>Label</span><input value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})} data-autofocus/></label><label className="field"><span>Variant SKU</span><input value={draft.variantSku} onChange={e=>setDraft({...draft,variantSku:e.target.value})}/></label><label><input type="checkbox" checked={draft.isActive} onChange={e=>setDraft({...draft,isActive:e.target.checked})}/> Active</label></div></Modal>}</>}

/* ---------------- Admin: analytics ---------------- */
function DateRangeBar({start,end,setStart,setEnd}:{start:string;end:string;setStart(v:string):void;setEnd(v:string):void}){
  const[now]=useState(()=>Date.now()),day=(back:number)=>new Date(now-back*86400000).toISOString().slice(0,10),today=day(0),preset=!start&&!end?"all":end===today&&start===day(6)?"7":end===today&&start===day(29)?"30":start===today&&end===today?"today":"custom";
  const pick=(id:string)=>{if(id==="all"){setStart("");setEnd("")}else if(id==="today"){setStart(today);setEnd(today)}else{setStart(day(id==="7"?6:29));setEnd(today)}};
  return <div className="filter-bar range-filter no-print" role="group" aria-label="Date range"><div className="seg">{[["all","All dates"],["today","Today"],["7","Last 7 days"],["30","Last 30 days"]].map(([id,l])=><button key={id} type="button" aria-pressed={preset===id} onClick={()=>pick(id!)}>{l}</button>)}</div><div className="fb-dates"><label className="field"><span>From (UTC)</span><input type="date" value={start} max={end||undefined} onChange={e=>setStart(e.target.value)}/></label><label className="field"><span>Through (UTC)</span><input type="date" value={end} min={start||undefined} onChange={e=>setEnd(e.target.value)}/></label></div>{preset==="custom"&&<span className="badge plain">Custom range</span>}{(start||end)&&<button type="button" className="btn btn-ghost btn-sm" onClick={()=>{setStart("");setEnd("")}}>Clear dates</button>}</div>}

function Bars({rows,format=(n:number)=>String(n)}:{rows:[string,number][];format?(n:number):string}){const max=Math.max(1,...rows.map(r=>r[1]));return <div className="bars">{rows.map(([label,value])=><div className="bar-row" key={label}><span className="muted">{label}</span><span className="track" role="img" aria-label={`${label}: ${format(value)}`}><span className="fill" style={{display:"block",width:`${(value/max)*100}%`}}/></span><span className="v">{format(value)}</span></div>)}</div>}
export function AdminAnalytics(){const{api}=useSession(),[startDate,setStartDate]=useState(""),[endDate,setEndDate]=useState(""),metrics=useLoad<ReportMetrics>(s=>api.reportMetrics({startDate:startDate||undefined,endDate:endDate||undefined},s),[startDate,endDate]),top=(metrics.data?.productMovement??[]).slice(0,8).map(row=>[row.productName,row.unitsReserved] as [string,number]);
  return <><PageHeader eyebrow="Insights" title="Analytics" description="Server-aggregated metrics. Date boundaries are inclusive UTC calendar dates." action={<div className="row no-print" style={{gap:8}}><NavLink className="btn btn-secondary" to="/admin/reports"><Icon name="download"/>Export CSV</NavLink><button type="button" className="btn btn-secondary" onClick={()=>window.print()}><Icon name="file"/>Print</button></div>}/><DateRangeBar start={startDate} end={endDate} setStart={setStartDate} setEnd={setEndDate}/>
    <div className="stats"><Stat icon="receipt" label="Total reservations" value={metrics.data?.totals.totalReservations??"…"}/><Stat icon="clock" label="Active reservations" value={metrics.data?.totals.activeReservations??"…"}/><Stat icon="check" label="Completed pickups" value={metrics.data?.totals.completedPickups??"…"}/><Stat icon="box" label="Unpicked units" value={metrics.data?.inventory.unpickedUnits??"…"}/><Stat accent icon="cash" label="Recorded sales" value={metrics.data?formatPeso(metrics.data.totals.recordedSales):"…"}/></div>
    <div className="grid-even"><Section flush={false} title="Reservations by status" description="Counts across the complete selected period.">{metrics.error?<ErrorState message={metrics.error} onRetry={metrics.reload}/>:metrics.data?<Bars rows={metrics.data.reservationsByStatus.map(row=>[row.status,Number(row.count)])}/>:<RowsSkeleton/>}</Section><Section flush={false} title="Most reserved products" description="Units reserved; completed pickup units are tracked separately.">{metrics.error?<ErrorState message={metrics.error} onRetry={metrics.reload}/>:metrics.data&&top.length?<Bars rows={top}/>:metrics.data?<Empty icon="chart" message="No product activity in this period."/>:<RowsSkeleton/>}</Section></div></>}

/* ---------------- Admin: reports (CSV export of live data) ---------------- */
export function AdminReports(){const{api}=useSession(),toast=useToast(),[busy,setBusy]=useState(""),[startDate,setStartDate]=useState(""),[endDate,setEndDate]=useState("");const reports:{key:"reservations"|"product-movement"|"inventory"|"pickups";title:string;text:string;icon:IconName}[]=[
    {key:"reservations",title:"Reservations",text:"Reservation status, institutional account, and timestamps.",icon:"receipt"},
    {key:"product-movement",title:"Product movement",text:"Reserved units and completed pickup units, ranked separately from revenue.",icon:"chart"},
    {key:"inventory",title:"Inventory summary",text:"Physical, reserved, available, and reorder quantities.",icon:"box"},
    {key:"pickups",title:"Pickup activity",text:"Completed recorded transactions and payment methods.",icon:"cash"},
  ];
  const run=async(r:typeof reports[number],format:"xlsx"|"pdf"|"csv")=>{const job=`${r.key}-${format}`;setBusy(job);try{const blob=await api.downloadReport(r.key,format,{startDate:startDate||undefined,endDate:endDate||undefined}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`bulldogs-xchange-${r.key}-${new Date().toISOString().slice(0,10)}.${format}`;document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);toast.push({tone:"success",title:`${r.title} ${format.toUpperCase()} exported`})}catch(e){toast.push({tone:"error",title:`${r.title} export failed`,message:errorMessage(e)})}finally{setBusy("")}};
  return <><PageHeader eyebrow="Insights" title="Reports" description="Admin-authorized Excel, PDF, and CSV exports generated from the complete filtered dataset." action={<button type="button" className="btn btn-secondary" onClick={()=>window.print()}><Icon name="file"/>Print</button>}/><DateRangeBar start={startDate} end={endDate} setStart={setStartDate} setEnd={setEndDate}/>
    <section className="panel flush report-list" aria-label="Available reports" aria-busy={!!busy}><div className="panel-head"><div><h2>Report exports</h2><p className="muted small">{startDate||endDate?`Applies to ${startDate||"the beginning"} through ${endDate||"today"} (UTC).`:"Applies to all dates. Choose a range above to narrow it."}</p><span className="sr-only" role="status" aria-live="polite">{busy?"Preparing report download":""}</span></div></div><ul>{reports.map(r=><li key={r.key}><span className="ic"><Icon name={r.icon}/></span><div className="main"><strong>{r.title}</strong><small>{r.text}</small></div><div className="row" style={{gap:6}}>{(["xlsx","pdf","csv"] as const).map(format=><button key={format} type="button" className="btn btn-sm" disabled={!!busy} onClick={()=>void run(r,format)}><Icon name="download"/>{busy===`${r.key}-${format}`?"Preparing…":format.toUpperCase()}</button>)}</div></li>)}</ul></section></>}

/* ---------------- Admin: settings & audit logs ---------------- */
export function AdminSettings(){const{api}=useSession(),settings=useLoad<SystemSetting[]>(s=>api.admin<SystemSetting[]>("settings",s));return <><PageHeader eyebrow="System" title="Settings" description="Allowlisted system settings currently applied by the backend."/><div className="notice" style={{marginBottom:20}}><Icon name="info"/><p>Settings are shown read-only here to prevent accidental changes during operations.</p></div><section className="panel flush"><Body state={settings} empty={<Empty icon="settings" message="No settings are configured."/>}>{list=><div className="table-wrap"><table><thead><tr><th>Setting</th><th>Value</th><th className="hide-sm">Last updated</th></tr></thead><tbody>{list.map(s=><tr key={s.key}><td className="mono">{s.key}</td><td><strong>{s.value}</strong></td><td className="hide-sm">{formatDateTime(s.updatedAt)}</td></tr>)}</tbody></table></div>}</Body></section></>}
export function AdminAuditLogs(){const{api}=useSession(),logs=useLoad<AuditLog[]>(s=>api.admin<AuditLog[]>("audit-logs",s)),[search,setSearch]=useState(""),rows=(logs.data??[]).filter(l=>!search||`${l.userEmail} ${l.action} ${l.entity} ${l.details??""}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  return <><PageHeader eyebrow="Insights" title="Audit logs" description="Who did what, and when. Approvals, role changes, stock changes, and pickups are all recorded." action={<button type="button" className="btn btn-secondary" onClick={logs.reload}><Icon name="refresh"/>Refresh</button>}/><div className="toolbar"><label className="search"><span className="sr-only">Search audit logs</span><Icon name="search"/><input type="search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search user, action, or entity"/></label></div><section className="panel flush"><Body state={{...logs,data:logs.data?rows:null}} empty={<Empty icon="history" message="No audit events match."/>}>{list=><div className="table-wrap"><table><thead><tr><th>When</th><th>User</th><th>Action</th><th className="hide-sm">Entity</th><th className="hide-sm">Details</th></tr></thead><tbody>{list.slice(0,300).map(l=><tr key={l.id}><td>{formatDateTime(l.createdAt)}</td><td>{l.userEmail}</td><td><span className="badge info plain">{l.action}</span></td><td className="hide-sm">{l.entity}</td><td className="hide-sm">{l.details??""}</td></tr>)}</tbody></table></div>}</Body></section></>}


/* ---------------- Admin: Barky AI management ---------------- */
interface BarkyFaq{id:number;question:string;answer:string;isActive:boolean;createdAt:string;updatedAt:string}
interface BarkyInsights{totalSessions:number;totalMessages:number;last24h:number}
export function AdminBarky(){
  const{api}=useSession();
  const toast=useToast();
  const faqs=useLoad<BarkyFaq[]>(s=>api.request<BarkyFaq[]>("admin/barky/faq",{signal:s}));
  const insights=useLoad<BarkyInsights>(s=>api.request<BarkyInsights>("admin/barky/insights",{signal:s}));
  const[tab,setTab]=useState<"faq"|"insights">("faq");
  const[editing,setEditing]=useState<BarkyFaq|null>(null);
  const[adding,setAdding]=useState(false);
  const[q,setQ]=useState("");const[a,setA]=useState("");const[saving,setSaving]=useState(false);
  const[deleting,setDeleting]=useState<number|null>(null);
  const openAdd=()=>{setAdding(true);setEditing(null);setQ("");setA("")};
  const openEdit=(f:BarkyFaq)=>{setEditing(f);setAdding(false);setQ(f.question);setA(f.answer)};
  const cancel=()=>{setAdding(false);setEditing(null);setQ("");setA("")};
  const save=async()=>{
    if(!q.trim()||!a.trim())return;
    setSaving(true);
    try{
      if(editing){
        await api.request(`admin/barky/faq/${editing.id}`,{method:"PUT",body:JSON.stringify({question:q.trim(),answer:a.trim(),isActive:editing.isActive})});
        toast.push({tone:"success",title:"FAQ updated"});
      }else{
        await api.request("admin/barky/faq",{method:"POST",body:JSON.stringify({question:q.trim(),answer:a.trim()})});
        toast.push({tone:"success",title:"FAQ created"});
      }
      cancel();faqs.reload();
    }catch(e){toast.push({tone:"error",title:"Save failed",message:errorMessage(e)});}
    finally{setSaving(false);}
  };
  const del=async(id:number)=>{
    setDeleting(id);
    try{
      await api.request(`admin/barky/faq/${id}`,{method:"DELETE"});
      toast.push({tone:"info",title:"FAQ deleted"});
      faqs.reload();
    }catch(e){toast.push({tone:"error",title:"Delete failed",message:errorMessage(e)});}
    finally{setDeleting(null);}
  };
  const toggleActive=async(f:BarkyFaq)=>{
    try{
      await api.request(`admin/barky/faq/${f.id}`,{method:"PUT",body:JSON.stringify({question:f.question,answer:f.answer,isActive:!f.isActive})});
      faqs.reload();
    }catch(e){toast.push({tone:"error",title:"Update failed",message:errorMessage(e)});}
  };
  return <><PageHeader eyebrow="System" title="Barky AI" description="Manage Barky's FAQ knowledge base and monitor usage."/>
    <div className="tabs" role="tablist">
      <button type="button" role="tab" className="tab" aria-selected={tab==="faq"} onClick={()=>setTab("faq")}>FAQs</button>
      <button type="button" role="tab" className="tab" aria-selected={tab==="insights"} onClick={()=>setTab("insights")}>Usage</button>
    </div>
    {tab==="faq"&&<>
      <div className="toolbar" style={{marginBottom:16}}><button type="button" className="btn" onClick={openAdd}><Icon name="plus"/>Add FAQ</button></div>
      {(adding||editing)&&<section className="panel" style={{marginBottom:20}}>
        <h2>{editing?"Edit FAQ":"New FAQ"}</h2>
        <div className="form-grid" style={{marginTop:16}}>
          <label className="field"><span>Question</span><input type="text" value={q} onChange={e=>setQ(e.target.value)} placeholder="What uniforms does Bulldogs Xchange carry?"/></label>
          <label className="field"><span>Answer</span><textarea rows={3} value={a} onChange={e=>setA(e.target.value)} placeholder="Answer…" style={{resize:"vertical"}}/></label>
          <div className="row" style={{gap:10}}><button type="button" className="btn" disabled={saving||!q.trim()||!a.trim()} onClick={()=>void save()}>{saving?"Saving…":"Save"}</button><button type="button" className="btn btn-secondary" onClick={cancel}>Cancel</button></div>
        </div>
      </section>}
      <section className="panel flush">
        <Body state={faqs} empty={<Empty icon="info" message="No FAQs yet. Add one to help Barky answer common questions."/>}>
          {list=><div className="table-wrap"><table><thead><tr><th>Question</th><th>Active</th><th className="act-col"><span className="sr-only">Actions</span></th></tr></thead>
          <tbody>{list.map(f=><tr key={f.id}>
            <td><strong>{f.question}</strong><small className="sub">{f.answer.slice(0,80)}{f.answer.length>80?"…":""}</small></td>
            <td><button type="button" className={`badge ${f.isActive?"success":"warning"} plain`} onClick={()=>void toggleActive(f)} title={f.isActive?"Deactivate":"Activate"} style={{cursor:"pointer"}}>{f.isActive?"Active":"Inactive"}</button></td>
            <td className="act-col" style={{display:"flex",gap:8}}><button type="button" className="btn btn-sm btn-secondary" onClick={()=>openEdit(f)}>Edit</button><button type="button" className="btn btn-sm btn-danger" disabled={deleting===f.id} onClick={()=>void del(f.id)}>{deleting===f.id?"…":"Delete"}</button></td>
          </tr>)}</tbody></table></div>}
        </Body>
      </section>
    </>}
    {tab==="insights"&&<section className="panel">
      {insights.error?<ErrorState message={insights.error} onRetry={insights.reload}/>:!insights.data?<RowsSkeleton/>:<dl className="detail-grid">
        <div><dt>Total sessions</dt><dd>{insights.data.totalSessions}</dd></div>
        <div><dt>Total messages (users)</dt><dd>{insights.data.totalMessages}</dd></div>
        <div><dt>Messages last 24h</dt><dd>{insights.data.last24h}</dd></div>
      </dl>}
    </section>}
  </>
}
